	// HYPOTHESIS-2: Lowering the KV threshold from 0.7 to 0.65 with slightly reduced magnitude (3.5 vs 4.0) will improve cache_warmup_e2e_ms below 4200 by earlier avoidance of memory-pressured instances during warmup
	// MECHANISM-2: During cache warmup, KV utilization rises quickly; catching pressure at 0.65 instead of 0.7 gives more headroom to route away before performance degrades
	// EXPECT-2: cache_warmup_e2e_ms < 4200
	// RESULT-2: REFUTED (actual=4213.0798744)

	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
